package org.jsoup.helper;

import org.jsoup.Connection;
import org.junit.Assert;
import org.junit.Test;

import java.net.MalformedURLException;
import java.net.URL;
import java.net.URISyntaxException;

public class UrlBuilderTest {

    @Test
    public void buildURLWithQueryTest() throws MalformedURLException, URISyntaxException {
        URL url = new URL("http://example.com?query=value");
        UrlBuilder urlBuilder = new UrlBuilder(url);

        URL expectedURL = new URL("http://example.com?query=value");
        URL actualURL = urlBuilder.build();

        Assert.assertEquals(expectedURL, actualURL);
    }

    @Test(expected = AssertionError.class)
    public void buildInvalidURLTest() throws MalformedURLException, URISyntaxException {
        URL url = new URL("http://example.com:8000");
        UrlBuilder urlBuilder = new UrlBuilder(url);
        urlBuilder.build();
    }

    @Test
    public void buildURLWithPunyCodeTest() throws MalformedURLException, URISyntaxException {
        URL url = new URL("http://non-ascii.com");
        UrlBuilder urlBuilder = new UrlBuilder(url);

        URL expectedURL = new URL("http://xn--non-ascii-4v9c.com/");
        URL actualURL = urlBuilder.build();

        Assert.assertEquals(expectedURL, actualURL);
    }

    @Test
    public void appendKeyValToURLTest() throws MalformedURLException {
        URL url = new URL("http://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(url);
        Connection.KeyVal keyVal = Connection.KeyVal.create("key", "value");
        urlBuilder.appendKeyVal(keyVal);

        String expectedQueryString = "key=value";
        String actualQueryString = urlBuilder.q.toString();

        Assert.assertEquals(expectedQueryString, actualQueryString);
    }

    @Test
    public void decodePartTest() throws MalformedURLException {
        String encodedPart = "part%20with%20spaces";
        String expectedDecodedPart = "part with spaces";

        String actualDecodedPart = UrlBuilder.decodePart(encodedPart);

        Assert.assertEquals(expectedDecodedPart, actualDecodedPart);
    }

    @Test
    public void normalizeQueryTest() {
        String query = "query with spaces";
        String expectedNormalizedQuery = "query+with+spaces";

        String actualNormalizedQuery = UrlBuilder.normalizeQuery(query);

        Assert.assertEquals(expectedNormalizedQuery, actualNormalizedQuery);
    }

    @Test
    public void normalizeRefTest() {
        String ref = "reference with spaces";
        String expectedNormalizedRef = "reference%20with%20spaces";

        String actualNormalizedRef = UrlBuilder.normalizeRef(ref);

        Assert.assertEquals(expectedNormalizedRef, actualNormalizedRef);
    }

}
